head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.fn_GetPar, scwin.fn_SetPar;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name search
 * @description 발행기관을 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.search = function() {
    let param = '';
    param += "&{P}V_LIST_STAT_CD=" + cmb_ListStatCd.getValue();
    param += "&{P}V_EXP_YY=" + cmb_ExpYy.getValue();
    param += "&{P}V_ISU_NM=" + txb_IsuNm.getValue();
    const dsNm = 'BNS_STRIP_STAT';
    const qryId = 'lds.stf.bnschg.select.listStripStat';
    $c.bns.fn_SearchBns("ULDBNS10300.xml", dts_List, dsNm, qryId, param);
};

/**
 * @method
 * @name getParListBndIsu
 * @description 상장종목 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParListBndIsu = function(arrPar) {
    arrPar[0] = {
        LIST_TYPE_CD: '2'
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParListBndIsu
 * @description 상장종목 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParListBndIsu = function(arrPar) {
    txb_IsuNm.setValue(arrPar[0].STD_CD);
};

/**
 * @method
 * @name getParStripSplitDtl
 * @description 스트립분리내역 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParStripSplitDtl = function(arrPar) {
    arrPar[0] = {
        STD_CD: dts_List.getCellData(dts_List.getRowPosition(), 'STD_CD')
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};
1;

/**
 * @method
 * @name gform_onload
 * @description 패널라운드처리
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    // 패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_Search);
    // 목록조회
    scwin.search();
};

/**
 * @method
 * @name bnt_Select_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.bnt_Select_onclick = function() {
    scwin.search();
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave("ULDBNS10300.xml", SCREN_PROCS_TP_CD_07);
    const fileNm = $c.ut.cGetToday("yyyymmdd") + '_' + '스트립현황조회';
    $c.data.downloadGridViewExcel(grd_List, {fileName: "스트립현황조회", type: 8});
};

/**
 * @method
 * @name img_IsuNm_onclick
 * @description img_IsuNm 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_IsuNm_onclick = function() {
    scwin.fn_GetPar = scwin.getParListBndIsu;
    scwin.fn_SetPar = scwin.setParListBndIsu;
    $c.bns.fn_PopListBndIsuSearch(img_IsuNm);
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    txb_TotalCnt.setValue("총 " + rowcount + "건");
};

/**
 * @method
 * @name grd_List_OnClick
 * @description grd_List 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnClick = function(row, colid) {
    if (row === 0) return;
    if (colid === 'STD_CD') {
        scwin.fn_GetPar = scwin.getParStripSplitDtl;
        $c.bns.fn_PopStripSplitDtlSearch(grd_List);
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
